package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

var _ = decimal.NewFromInt

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                      // PIC X len=1 = "N"
var WsLabel string = strings.Repeat(" ", 20)    // PIC X(20) len=20 = SPACES
var WsACount int64 = 0                         // PIC 99 len=2 = 0
var WsTotalA int64 = 0                         // PIC 999 len=3 = 0
var WsCount int64 = 0                          // PIC 999 len=3 = 0

var PartRecData PartRec

var partFile *os.File
var partReader *bufio.Reader

func trunc(width int, v int64) int64 {
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	if v >= 0 {
		return v % mod
	}
	return -((-v) % mod)
}

func fmtPic(width int, v int64) string {
	tv := trunc(width, v)
	if tv < 0 {
		// not expected for this program (all unsigned)
		return fmt.Sprintf("%0*d", width, tv)
	}
	return fmt.Sprintf("%0*d", width, tv)
}

func delimitedBySpace(s string) string {
	if idx := strings.Index(s, " "); idx >= 0 {
		return s[:idx]
	}
	return s
}

func getNextLine() (string, bool) {
	if partReader == nil {
		return "", false
	}
	s, err := partReader.ReadString('\n')
	if err != nil && err != io.EOF {
		return "", false
	}
	if err == io.EOF && len(s) == 0 {
		return "", false
	}
	if len(s) > 0 && s[len(s)-1] == '\n' {
		s = s[:len(s)-1]
		if len(s) > 0 && s[len(s)-1] == '\r' {
			s = s[:len(s)-1]
		}
	} else {
		if len(s) > 0 && s[len(s)-1] == '\r' {
			s = s[:len(s)-1]
		}
	}
	return s, true
}

// Paragraphs

func ReadPara() {
	if partReader == nil {
		WsEofFlag = "Y"
		return
	}
	line, ok := getNextLine()
	if !ok {
		WsEofFlag = "Y"
		return
	}
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	PartRecData.LbPart = line[0:8]
	PartRecData.LbRegion = line[8:11]
	serialStr := line[11:15]
	trimmed := strings.TrimSpace(serialStr)
	if trimmed == "" {
		PartRecData.LbSerial = 0
	} else {
		var v int64
		for _, ch := range trimmed {
			if ch >= '0' && ch <= '9' {
				v = v*10 + int64(ch-'0')
			}
		}
		PartRecData.LbSerial = trunc(4, v)
	}
}

func ProcessPara() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = trunc(2, 0)

	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	cnt := strings.Count(PartRecData.LbPart, "A")
	WsACount = trunc(2, WsACount+int64(cnt))

	// STRING ... INTO WS-LABEL
	dest := make([]byte, 20)
	for i := range dest {
		dest[i] = ' '
	}
	pos := 0
	appendSrc := func(src string) {
		for i := 0; i < len(src) && pos < 20; i++ {
			dest[pos] = src[i]
			pos++
		}
	}
	regionSrc := delimitedBySpace(PartRecData.LbRegion)
	appendSrc(regionSrc)
	appendSrc("-")
	partSrc := delimitedBySpace(PartRecData.LbPart)
	appendSrc(partSrc)
	appendSrc("-")
	serialSrc := fmtPic(4, PartRecData.LbSerial)
	appendSrc(serialSrc)

	WsLabel = string(dest)

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA = trunc(3, WsTotalA+WsACount)
	// ADD 1 TO WS-COUNT
	WsCount = trunc(3, WsCount+1)

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	countStr := fmtPic(2, WsACount)
	fmt.Printf("%s A=%s\n", WsLabel, countStr)

	ReadPara()
}

func SummaryPara() {
	countStr := fmtPic(3, WsCount)
	totalStr := fmtPic(3, WsTotalA)
	fmt.Printf("LABELS: %s A-TOTAL: %s\n", countStr, totalStr)
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		WsEofFlag = "Y"
		partReader = nil
		partFile = nil
	} else {
		partFile = f
		partReader = bufio.NewReader(f)
		WsEofFlag = "N"
	}

	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	if partFile != nil {
		partFile.Close()
	}
	SummaryPara()
}

func main() {
	MainPara()
}
